        "source_role": "refreshment_item",
        "target_role": "placement_surface",
        "operation_count": 2,
        "reuse_policy": "REUSABLE_ACROSS_TARGETS",
        "anchor_role": "seating_area"
      },
      {
        "id": "op_2",
        "operation": "relocate_entertainment_control",
        "source_role": "entertainment_control",
        "target_role": "placement_surface",
        "operation_count": 1,
